    'usage: dart run scripts/sqlite3_native_assets_prewarm.dart '
    '[--package-root <dir>]... [--targets auto|android|arm64-ios|<abi>-<os>] '
    '[--attempts <n>] [--backoff-base-seconds <s>] [--url-pattern <p>] '
