  }

  /// All prebuilt sqlite3 libraries attached to GH releases.
  static Iterable<PrebuiltSqliteLibrary> get all sync* {
    for (final MapEntry(key: os, value: abis) in _supportedAbis.entries) {
      for (final abi in abis) {
