    if tid not in raw_ids:
        print('UNKNOWN threadId:', tid); ok = False
    elif raw_ids[tid] != r['inReplyToId']:
        print('MISMATCH inReplyToId for', tid, r['inReplyToId'], 'expected', raw_ids[tid]); ok = False
