    if not os.path.isfile(p):
        print('MISSING file:', p); ok = False
    elif 'inReplyToId' not in r or 'threadId' not in r:
        ok = False
missing = set(raw_ids) - {r['threadId'] for r in replies}
if missing: print('UNANSWERED threads:', missing); ok = False
# no inline bodies in JSON
for r in replies:
    assert set(r.keys()) == {'inReplyToId','threadId','reply'}, r.keys()
print('ALL VERIFIED' if ok else 'FAILED')
"

